local Plasma = require(game.ReplicatedStorage.Packages.Plasma)
local UserInputService = game:GetService("UserInputService")

local create = Plasma.create
local createConnect = require(game.ReplicatedStorage.Packages.Plasma.createConnect)
return Plasma.widget(function(placeHolder, textValue: string?)
	local textValue, setTextValue = Plasma.useState(textValue or "")
	local refs = Plasma.useInstance(function(ref)
		local connect = createConnect()
		local style = Plasma.useStyle()
		local connection

		local result = create("TextBox", {
			[ref] = "input",
			Font = Enum.Font.SourceSans,
			TextColor3 = style.textColor,
			Size = UDim2.new(0, 100, 0, 20),
			TextSize = 20,
			RichText = false,
			Text = "",
			PlaceholderText = placeHolder or "",
			BorderSizePixel = 1,
			BackgroundColor3 = Color3.fromRGB(40, 40, 40),
			BorderColor3 = Color3.fromRGB(255, 255, 255),
			Focused = function()
				textValue = ""
				setTextValue("")

				if connection then
					connection:Disconnect()
				end

				connection = connect(UserInputService, "InputBegan", function(moveInput)
					if moveInput.UserInputType ~= Enum.UserInputType.Keyboard then
						return
					end

					if moveInput.KeyCode.Value >= 97 and moveInput.KeyCode.Value <= 122 then
						-- a-z
						textValue = textValue .. tostring(moveInput.KeyCode.Name)
					elseif moveInput.KeyCode.Value >= 48 and moveInput.KeyCode.Value <= 57 then
						-- 0-9
						textValue = textValue .. tostring(moveInput.KeyCode.Value - 48)
					elseif moveInput.KeyCode == Enum.KeyCode.Backspace then
						-- 退格键
						textValue = textValue:sub(1, -2)
					else
						ref.input.Text = ""
						ref.input.Text = textValue
						return
					end

					setTextValue(string.lower(textValue))
				end)
			end,

			FocusLost = function(input)
				if connection then
					connection:Disconnect()
					connection = nil
				end
			end,
		})

		return result
	end)

	refs.input.Text = textValue

	return {
		text = function()
			return refs.input.Text
		end,
		setValue = function(value)
			refs.input.Text = value
		end,
	}
end)
